const COLUMN_LABELS={code:'Numéro',name:'Nom et prénoms',phone:'Téléphone',locality:'Localité',share_value:'Valeur de la part',status:'Statut',meeting_date:'Date de réunion',notes:'Observations',member_name:'Membre',cycle_name:'Cycle',shares:'Nombre de parts',amount:'Montant',principal:'Capital',interest_total:'Intérêts totaux',paid:'Montant remboursé',principal_amount:'Capital remboursé',interest_amount:'Intérêts remboursés',kind:'Type',description:'Description',profit:'Bénéfice',created_at:'Date de création',email:'Courriel',role:'Rôle',active:'Actif',action:'Action',target:'Élément concerné',id:'Identifiant',plan:'Formule',plan_expires_at:'Fin de validité',duration_months:'Durée (mois)',end_date:'Date de fin',frequency_days:'Fréquence (jours)',weekday:'Jour de réunion',absence_fine:'Amende pour absence',start_at:'Date de début',due_at:'Échéance finale',repayment_frequency:'Remboursement',penalty_percent:'Pénalité (%)',penalty_amount:'Pénalité payée'};
const VALUE_LABELS={active:'Actif',inactive:'Inactif',archived:'Archivé',pending:'En attente',approved:'Approuvé',rejected:'Refusé',paid:'Soldé',unpaid:'Impayé',closed:'Clôturé',open:'Ouvert',admin:'Administrateur',agent:'Agent',member:'Membre',superadmin:'Administrateur général',free:'Gratuit',standard:'Standard',business:'Professionnel',in:'Entrée',out:'Sortie',deposit:'Dépôt',withdrawal:'Retrait',login:'Connexion',user_created:'Utilisateur créé',password_changed:'Mot de passe modifié'};
const labelValue=value=>{if(value===1||value==='1')return 'Oui';if(value===0||value==='0')return 'Non';return VALUE_LABELS[String(value)]??value??''};
let csrf='',me=null,section='summary',lastPromo=0,cache={},cacheAt={},requestSerial=0;const CACHE_TTL=20000;const pageUrl=p=>'/'+p;const requestedPage=()=>{const path=location.pathname.replace(/^\/+|\/+$/g,'')||new URL(location.href).searchParams.get('page')||'summary';return path==='savings'?'meetings':path};const $=x=>document.querySelector(x),money=n=>new Intl.NumberFormat('fr-FR').format(n||0)+' F',escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){let x=$('#toast');x.textContent=msg;x.style.display='block';setTimeout(()=>x.style.display='none',4200)}
async function req(path,data){let options={credentials:'same-origin',headers:{}};if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','x-csrf-token':csrf};options.body=JSON.stringify(data)}let response=await fetch(path,options),json=await response.json().catch(()=>({error:'Réponse serveur invalide'}));if(!response.ok)throw Error(json.error||'Erreur réseau');if(data!==undefined&&(path==='/api/save'||path==='/api/change-password')){cache={};cacheAt={}}return json}
function openModal(title,html){$('#modal .modal').classList.remove('wide-detail');$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').hidden=false;wireEyes()}
function closeModal(){$('#modal').hidden=true}
$('#closeModal').onclick=closeModal;function wireEyes(){document.querySelectorAll('[data-eye]').forEach(b=>b.onclick=()=>{let i=document.getElementById(b.dataset.eye);i.type=i.type==='password'?'text':'password';b.textContent=i.type==='password'?'◉':'⊘'})}wireEyes();
$('#register').onclick=async()=>{
 try{
  let token=(await req('/api/register-token')).token;
  openModal('Créer ma banque de gestion AVEC',`<p class="muted">Créez votre association et son administrateur. Chaque AVEC possède un espace de gestion indépendant. Votre formule Gratuite de 10 jours démarre à l’inscription.</p><form id="registerForm"><label>Nom de votre AVEC<input name="organization" maxlength="150" required placeholder="Ex. AVEC Solidarité de Diabo"></label><label>Localité<input name="locality" maxlength="100" placeholder="Ville ou village"></label><label>Nom et prénoms de l’administrateur<input name="name" maxlength="150" required></label><label>E-mail de connexion<input name="email" type="email" autocomplete="email" maxlength="200" required></label><label>Mot de passe administrateur (12 caractères minimum)<div class="password-wrap"><input id="regPassword" name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required><button type="button" class="eye" data-eye="regPassword" aria-label="Afficher ou masquer le mot de passe">◉</button></div></label><label>Confirmer le mot de passe<div class="password-wrap"><input id="regConfirm" name="password_confirm" type="password" minlength="12" maxlength="128" autocomplete="new-password" required><button type="button" class="eye" data-eye="regConfirm" aria-label="Afficher ou masquer le mot de passe">◉</button></div></label><p class="tiny">En créant votre compte, vous acceptez que les informations de votre AVEC soient conservées pour fournir le service.</p><button class="primary full">Créer mon AVEC · Essai gratuit 10 jours</button></form>`);
  $('#registerForm').onsubmit=async e=>{
   e.preventDefault();let form=e.target,data=Object.fromEntries(new FormData(form));
   if(data.password!==data.password_confirm)return toast('Les deux mots de passe sont différents');
   let btn=form.querySelector('button.primary');btn.disabled=true;
   try{let r=await req('/api/register',{...data,registration_token:token});closeModal();$('#email').value=data.email;$('#password').value='';toast(r.message+' Connectez-vous pour commencer.')}catch(err){toast(err.message);btn.disabled=false;token=(await req('/api/register-token')).token}
  };
 }catch(e){toast(e.message)}
};
$('#forgot').onclick=()=>openModal('Mot de passe oublié',`<p>La demande sera transmise au responsable habilité. L'administrateur est assisté par le Super Admin ; l'agent par son administrateur.</p><form id="resetForm"><label>E-mail du compte<input name="email" type="email" required></label><button class="primary full">Envoyer la demande</button></form>`);
$('#modal').addEventListener('submit',async e=>{if(e.target.id==='resetForm'){e.preventDefault();try{await req('/api/public-reset',Object.fromEntries(new FormData(e.target)));toast('Demande enregistrée si le compte existe');closeModal()}catch(err){toast(err.message)}}});
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{let r=await req('/api/login',{email:$('#email').value,password:$('#password').value});csrf=r.csrf;me=r.user;$('#password').value='';await enter()}catch(err){toast(err.message)}};
$('#logout').onclick=async()=>{try{await req('/api/logout',{})}catch{}location.reload()};
const menus=[['summary','▦ Tableau de bord'],['members','♙ Membres'],['cycles','◷ Cycles'],['meetings','▤ Réunions et épargnes'],['loans','⇄ Crédits'],['repayments','↩ Remboursements'],['solidarity','♡ Solidarité'],['expenses','− Dépenses'],['distributions','▥ Partages'],['reports','▧ Rapports'],['settings','⚙ Paramètres'],['users','♙ Utilisateurs'],['audit','◉ Journal'],['superadmin','★ Administration générale']];
async function enter(){let r=await req('/api/session');csrf=r.csrf||csrf;me=r.user;me.plan=r.plan;me.expires=r.expires;$('#login').hidden=true;$('#app').hidden=false;$('#who').textContent=`${me.name} · ${me.role}`;$('#planBadge').textContent=me.role==='superadmin'?'ADMINISTRATION GÉNÉRALE':`FORMULE ${labelValue(me.plan||'')}`;let allowed=menus.filter(([s])=>me.role==='superadmin'?['superadmin','settings','audit'].includes(s):me.role==='member'?['summary','settings'].includes(s):!['superadmin'].includes(s)&&(!['users','audit','expenses','distributions'].includes(s)||me.role==='admin')).map(x=>x[0]);$('#nav').innerHTML=menus.filter(([s])=>allowed.includes(s)).map(([k,v])=>`<a href="${pageUrl(k)}" data-menu="${k}">${v}</a>`).join('');document.querySelectorAll('[data-menu]').forEach(a=>a.onclick=e=>{e.preventDefault();show(a.dataset.menu)});const first=allowed.includes(requestedPage())?requestedPage():(me.role==='superadmin'?'superadmin':'summary');await show(first,{replace:true});window.onpopstate=()=>{let target=requestedPage();if(allowed.includes(target))show(target,{history:false});else show(first,{replace:true})}}
async function show(s,{history=true,replace=false,force=false}={}){if(!menus.some(x=>x[0]===s))return;const permitted=!!document.querySelector(`[data-menu="${s}"]`);if(!permitted)return;section=s;const ticket=++requestSerial;if(history||replace){let url=pageUrl(s);if(replace)window.history.replaceState({page:s},'',url);else if(location.pathname!==url)window.history.pushState({page:s},'',url)}document.querySelectorAll('[data-menu]').forEach(b=>{b.classList.toggle('active',b.dataset.menu===s);if(b.dataset.menu===s)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#heading').textContent=menus.find(x=>x[0]===s)?.[1].replace(/^[^ ]+ /,'')||s;document.title=$('#heading').textContent+' · AVEC Manager Pro';if(s==='solidarity'){await solidarityDashboard();return}if(s==='settings'){settings();return}if(s==='reports'){reports();return}if(s==='distributions'){partagePage();return}if(s==='superadmin'){$('#view').innerHTML='<div class="card muted">Chargement de la gestion centrale…</div>';try{await superadmin()}catch(e){if(ticket===requestSerial)$('#view').innerHTML=`<div class="card hint">${escape(e.message)}</div>`}return}try{let d;if(!force&&cacheAt[s]&&Date.now()-cacheAt[s]<CACHE_TTL){d=cache[s]}else{$('#view').innerHTML='<div class="card muted">Chargement de cette section uniquement…</div>';let r=await req('/api/load?section='+encodeURIComponent(s));d=r.data;cache[s]=d;cacheAt[s]=Date.now()}if(ticket!==requestSerial)return;if(s==='summary'){$('#view').innerHTML='<div class="grid">'+[['Membres',d.members],['Épargne cumulée',money(d.savings)],['Crédits accordés',money(d.loans)],['Capital restant dû',money(d.principalDue)],['Intérêts encaissés',money(d.interest)],['Dépenses',money(d.expenses)],['Fonds de solidarité',money(d.solidarity)]].map(([a,b])=>`<div class="card"><small>${a}</small><div class="num">${b}</div></div>`).join('')+'</div><div class="card">Les données financières sont calculées côté serveur à partir des opérations D1.</div>'}else renderTable(s,d);if(me.plan==='free'&&Date.now()-lastPromo>=900000&&s!=='settings')promo()}catch(e){if(ticket===requestSerial)$('#view').innerHTML=`<div class="card hint">${escape(e.message)} <button class="secondary" id="retrySection">Réessayer</button></div>`;let retry=$('#retrySection');if(retry)retry.onclick=()=>show(s,{force:true})}}
const configs={members:{title:'Ajouter un membre',save:'member',fields:[['name','Nom et prénoms','text'],['phone','Téléphone','text'],['locality','Localité','text']]},cycles:{title:'Ouvrir un cycle',save:'cycle',fields:[['name','Nom du cycle','text'],['share_value','Valeur d’une part (FCFA)','number'],['duration_months','Durée du cycle','duration'],['start_date','Date de début','date'],['end_date_preview','Date de fin calculée','readonly'],['weekday','Jour de réunion','weekday'],['frequency_days','Fréquence des réunions','frequency'],['absence_fine','Amende individuelle pour absence (FCFA)','number']]},meetings:{title:'Nouvelle réunion',save:'meeting',fields:[['cycle_id','Cycle','cycle'],['meeting_date','Date','date'],['notes','Notes','text']]},savings:{title:'Nouvelle épargne',save:'saving',fields:[['cycle_id','Cycle','cycle'],['member_id','Membre','member'],['shares','Nombre de parts','number']]},loans:{title:'Accorder un crédit',save:'loan',fields:[['cycle_id','Cycle','cycle'],['member_id','Membre','member'],['principal','Capital en FCFA','number'],['rate_percent','Intérêt forfaitaire (%)','number'],['term_days','Durée (jours)','number'],['disbursement_date','Date de décaissement','date'],['repayment_frequency','Type de remboursement','repayment_frequency'],['penalty_percent','Pénalité (%)','number'],['penalty_frequency','Fréquence pénalité','penalty_frequency']]},repayments:{title:'Remboursement',save:'repayment',fields:[['loan_id','Crédit','loan'],['repayment_type','Type de règlement','repayment_type'],['amount','Montant reçu','number'],['payment_date','Date de paiement','date']]},solidarity:{title:'Mouvement de solidarité',save:'solidarity',fields:[['cycle_id','Cycle','cycle'],['kind','Type','kind'],['amount','Montant','number'],['notes','Motif','text']]},expenses:{title:'Dépense du cycle',save:'expense',fields:[['cycle_id','Cycle','cycle'],['amount','Montant','number'],['description','Description','text']]}};
const fieldsShown={members:['code','name','phone','locality'],cycles:['name','share_value','duration_months','start_at','end_date','frequency_days','weekday','absence_fine','status'],meetings:['meeting_date','notes'],savings:['member_name','cycle_name','shares','amount'],loans:['member_name','principal','interest_total','paid','due_at','status'],repayments:['member_name','amount','principal_amount','interest_amount'],solidarity:['kind','amount','notes'],expenses:['description','amount'],distributions:['cycle_name','profit','created_at'],users:['name','email','role','active'],audit:['action','target','created_at']};
function repaymentList(rows){
 const date=v=>v?new Date(v).toLocaleDateString('fr-FR'):'—';
 const body=rows.map(r=>{const debt=Math.max(0,Number(r.loan_principal||0)+Number(r.loan_interest||0)+Number(r.loan_penalties||0)-Number(r.cumulative_paid||0));
 const balance=debt?`<span class="debt-due">${money(debt)}</span>`:money(0);
 const status=debt?'Partiellement remboursé':'Soldé';
 return `<tr><td data-label="Membre">${escape(r.member_name)}</td><td data-label="Capital accordé">${money(r.loan_principal)}</td><td data-label="Intérêt">${money(r.loan_interest)}</td><td data-label="Pénalité">${money(r.penalty_amount||0)}</td><td data-label="Remboursement du jour">${money(r.amount)}</td><td data-label="Date du jour">${date(r.created_at)}</td><td data-label="Reste à payer">${balance}</td><td data-label="Statut"><div class="repay-actions"><span class="pill">${status}</span>${me.role==='admin'?`<button class="secondary" data-rp-edit="${escape(r.id)}">Modifier</button><button class="secondary danger" data-rp-del="${escape(r.id)}">Supprimer</button>`:''}<button class="secondary" data-rp-receipt="${escape(r.id)}">Reçu</button></div></td></tr>`;
 }).join('');
 $('#view').innerHTML=`<div class="card repay-list"><div class="toolbar"><strong>${rows.length} remboursement(s)</strong><button class="primary" id="add">+ Nouveau remboursement</button></div><div class="table-wrap"><table><thead><tr>${['Membre','Capital accordé','Intérêt','Pénalité','Remboursement du jour','Date du jour','Reste à payer','Statut'].map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table>${!rows.length?'<div class="empty">Aucun remboursement enregistré</div>':''}</div><p class="muted">Le reste à payer est calculé après chaque règlement, selon les montants de crédit enregistrés et les pénalités comptabilisées. Les pénalités nouvelles non encore calculées sont exclues.</p></div>`;
 $('#add').onclick=()=>repaymentForm();
 document.querySelectorAll('[data-rp-edit]').forEach(b=>b.onclick=()=>repaymentCorrection(rows.find(r=>r.id===b.dataset.rpEdit),false));
 document.querySelectorAll('[data-rp-del]').forEach(b=>b.onclick=()=>repaymentCorrection(rows.find(r=>r.id===b.dataset.rpDel),true));
 document.querySelectorAll('[data-rp-receipt]').forEach(b=>b.onclick=()=>repaymentReceipt(rows.find(r=>r.id===b.dataset.rpReceipt)));
}
function repaymentCorrection(r,remove){if(!r)return;openModal(remove?'Supprimer le remboursement':'Modifier le remboursement',`<p class="hint">${remove?'Cette suppression annule le dernier paiement du crédit.':'Seul le montant du dernier paiement peut être rectifié.'} Les mouvements comportant des pénalités déjà comptabilisées nécessitent une correction comptable supervisée.</p><form id="repayCorrection"><p><strong>${escape(r.member_name)}</strong> — ${money(r.amount)} du ${new Date(r.created_at).toLocaleDateString('fr-FR')}</p>${remove?'':`<label>Montant corrigé (FCFA)<input name="amount" type="number" min="1" step="1" value="${r.amount}" required></label>`}<label>Mot de passe administrateur<div class="password-wrap"><input id="repayConfirmPwd" type="password" name="password" required><button class="eye" type="button" data-eye="repayConfirmPwd">◉</button></div></label><button class="primary full ${remove?'danger':''}" type="submit">${remove?'Confirmer la suppression':'Enregistrer la modification'}</button></form>`);wireEyes();$('#repayCorrection').onsubmit=async e=>{e.preventDefault();let btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{await req('/api/save',{section:remove?'repayment_delete':'repayment_update',data:{id:r.id,amount:remove?undefined:Number(e.target.elements.amount.value),password:e.target.elements.password.value}});closeModal();toast(remove?'Remboursement supprimé':'Remboursement modifié');show('repayments',{force:true})}catch(er){toast(er.message);btn.disabled=false}}}
function repaymentReceipt(r){if(!r)return;const dt=new Date(r.created_at).toLocaleDateString('fr-FR');const html=`<div class="receipt-print"><h2>AVEC MANAGER PRO — REÇU DE REMBOURSEMENT</h2><p><strong>Membre :</strong> ${escape(r.member_name)}</p><p><strong>Date du règlement :</strong> ${dt}</p><p><strong>Référence :</strong> ${escape(r.id)}</p><p><strong>Capital accordé :</strong> ${money(r.loan_principal)}</p><p><strong>Intérêts contractuels :</strong> ${money(r.loan_interest)}</p><p><strong>Capital remboursé ce jour :</strong> ${money(r.principal_amount)}</p><p><strong>Intérêts payés ce jour :</strong> ${money(r.interest_amount)}</p><p><strong>Pénalités payées :</strong> ${money(r.penalty_amount||0)}</p><h3>Total reçu : ${money(r.amount)}</h3><p>Document généré le ${new Date().toLocaleDateString('fr-FR')}</p></div>`;openModal('Reçu de remboursement',html+'<button class="primary full" id="printRepay">Imprimer / Enregistrer en PDF</button>');$('#printRepay').onclick=()=>{const w=window.open('','_blank');if(!w)return toast('Autorisez la fenêtre d’impression');w.document.write(`<html lang="fr"><head><meta charset="utf-8"><title>Reçu de remboursement</title><style>@page{size:A4;margin:18mm}body{font:14px Arial,sans-serif;color:#113f32;line-height:1.7}h2{border-bottom:3px solid #caa335;padding-bottom:12px}h3{padding:12px;background:#eaf5ef}p{border-bottom:1px solid #e1e8e4}</style></head><body>${html}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}}
function renderTable(s,rows){if(!Array.isArray(rows))rows=[];if(s==='repayments'){repaymentList(rows);return;}if(s==='expenses'){expenseList(rows);return;}if(s==='meetings'||s==='savings'){renderCalendar('meetings');return;}let cols=fieldsShown[s]||Object.keys(rows[0]||{}).filter(k=>!k.includes('password'));$('#view').innerHTML=`<div class="card"><div class="toolbar"><strong>${rows.length} enregistrement(s)</strong>${configs[s]&&me.role!=='member'?`<button class="primary" id="add">+ ${configs[s].title}</button>`:''}${s==='users'?'<button class="primary" id="addUser">+ Utilisateur</button>':''}${s==='distributions'?'<button class="primary" id="preview">Prévisualiser le partage</button>':''}</div><div class="table-wrap"><table><thead><tr>${cols.map(x=>`<th>${escape(COLUMN_LABELS[x]||x)}</th>`).join('')}${['users','cycles','members','loans'].includes(s)?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(row=>`<tr>${cols.map(c=>`<td>${escape(['created_at','start_at','due_at'].includes(c)?new Date(row[c]).toLocaleDateString('fr-FR'):c==='weekday'?['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'][row[c]]:['status','role','kind','active','plan','action'].includes(c)?labelValue(row[c]):row[c])}</td>`).join('')}${s==='loans'?`<td><button class="secondary" data-loan-report="${row.id}">Rapport</button> ${me.role==='admin'?`<button class="secondary" data-loan-edit="${row.id}">Modifier</button> <button class="secondary danger" data-loan-delete="${row.id}">Supprimer</button>`:''}</td>`:''}${s==='members'?`<td>${me.role==='admin'?`<button class="secondary" data-edit-member="${row.id}">Modifier</button> <button class="secondary danger" data-delete-member="${row.id}">${row.active?'Supprimer':'Supprimer définitivement'}</button>`:'—'}</td>`:''}${s==='cycles'?`<td>${me.role==='admin'?`${row.status==='active'?`<button class="secondary" data-edit-cycle="${row.id}">Modifier</button> <button class="secondary danger" data-close-cycle="${row.id}">Clôturer</button>`:''} <button class="secondary danger" data-delete-cycle="${row.id}">Supprimer</button>`:'—'}</td>`:''}${s==='users'?`<td><button class="secondary" data-reset="${row.id}">Réinitialiser</button> <button class="secondary" data-user-status="${row.id}" data-active="${row.active}">${row.active?'Suspendre':'Activer'}</button></td>`:''}</tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">Aucun enregistrement pour le moment</div>':''}</div></div>`;if(s==='loans'){const tbl=$('#view table');if(tbl){tbl.querySelector('thead tr:last-child th:last-child')?.remove();tbl.querySelectorAll('tbody tr').forEach(tr=>{const action=tr.lastElementChild,stat=action?.previousElementSibling;if(action&&stat){stat.append(document.createElement('br'));while(action.firstChild)stat.appendChild(action.firstChild);action.remove();}})}document.querySelectorAll('[data-loan-report]').forEach(b=>b.onclick=()=>loanReport(b.dataset.loanReport));document.querySelectorAll('[data-loan-edit]').forEach(b=>b.onclick=()=>loanForm(b.dataset.loanEdit));document.querySelectorAll('[data-loan-delete]').forEach(b=>b.onclick=()=>loanDelete(b.dataset.loanDelete));}if(s==='members'){document.querySelectorAll('[data-edit-member]').forEach(b=>b.onclick=()=>editMember(b.dataset.editMember));document.querySelectorAll('[data-delete-member]').forEach(b=>b.onclick=()=>deleteMember(b.dataset.deleteMember));}if(s==='cycles'){document.querySelectorAll('[data-close-cycle]').forEach(b=>b.onclick=()=>closeCycle(b.dataset.closeCycle));document.querySelectorAll('[data-edit-cycle]').forEach(b=>b.onclick=()=>editCycle(b.dataset.editCycle));document.querySelectorAll('[data-delete-cycle]').forEach(b=>b.onclick=()=>deleteCycle(b.dataset.deleteCycle));}if($('#add'))$('#add').onclick=()=>makeForm(s);if($('#addUser'))$('#addUser').onclick=()=>userForm(false);if($('#preview'))$('#preview').onclick=preview;if(s==='users'){document.querySelectorAll('[data-reset]').forEach(x=>x.onclick=()=>resetUser(x.dataset.reset));document.querySelectorAll('[data-user-status]').forEach(x=>x.onclick=async()=>{try{await req('/api/save',{section:'user_status',data:{id:x.dataset.userStatus,active:Number(x.dataset.active)?0:1}});show('users')}catch(e){toast(e.message)}})}}
async function options(type){let name={member:'members',cycle:'cycles',loan:'loans'}[type];let rows=cache[name]||((await req('/api/load?section='+name)).data);cache[name]=rows;return rows.filter(x=>type!=='cycle'||x.status==='active').map(x=>`<option value="${escape(x.id)}">${escape(x.name||x.member_name||x.id.slice(0,10))}</option>`).join('')}
async function makeForm(s){if(s==='loans')return loanForm();if(s==='repayments')return repaymentForm();let c=configs[s],f='';for(let [name,label,type] of c.fields){if(['cycle','member','loan'].includes(type))f+=`<label>${label}<select name="${name}" required>${await options(type)}</select></label>`;else if(type==='repayment_frequency')f+=`<label>${label}<select name="${name}"><option value="weekly">Par semaine</option><option value="monthly">Par mois</option></select></label>`;else if(type==='penalty_frequency')f+=`<label>${label}<select name="${name}"><option value="daily">Par jour</option><option value="monthly">Par mois</option></select></label>`;else if(type==='repayment_type')f+=`<label>${label}<select name="${name}"><option value="partial">Partiel</option><option value="total">Total</option></select></label>`;else if(type==='duration')f+=`<label>${label}<select name="${name}"><option value="9">9 mois</option><option value="12">12 mois</option></select></label>`;else if(type==='weekday')f+=`<label>${label}<select name="${name}">${['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'].map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></label>`;else if(type==='frequency')f+=`<label>${label}<select name="${name}"><option value="7">Chaque semaine</option><option value="14">Toutes les deux semaines</option></select></label>`;else if(type==='readonly')f+=`<label>${label}<input name="${name}" readonly placeholder="Calcul automatique"></label>`;else if(type==='kind')f+=`<label>Type<select name="kind"><option value="income">Entrée</option><option value="expense">Sortie</option></select></label>`;else f+=`<label>${label}<input name="${name}" type="${type}" ${type==='number'?'min="0" step="any"':''} ${type!=='text'?'required':''}></label>`}openModal(c.title,`<form id="genericForm">${f}<button class="primary full">Enregistrer</button></form>`);if(s==='cycles'){let form=$('#genericForm'),update=()=>{let date=form.elements.start_date.value,months=Number(form.elements.duration_months.value);if(!date)return;let [y,m,d]=date.split('-').map(Number),first=new Date(Date.UTC(y,m-1+months,1)),last=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();form.elements.end_date_preview.value=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth(),Math.min(d,last))).toISOString().slice(0,10)};form.elements.start_date.onchange=update;form.elements.duration_months.onchange=update;}$('#genericForm').onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));e.target.querySelector('button').disabled=true;try{await req('/api/save',{section:c.save,data:b});closeModal();cache={};toast('Enregistrement réussi');show(s)}catch(er){toast(er.message);e.target.querySelector('button').disabled=false}}}
