async function editCycle(cycleId){
 try{
  const rows=cache.cycles||(await req('/api/load?section=cycles')).data;
  const cy=rows.find(x=>x.id===cycleId);
  if(!cy||cy.status!=='active')return toast('Seul un cycle actif peut être modifié');
  const c=configs.cycles;
  let formHtml='';
  for(const [name,label,type] of c.fields){
   const val=name==='start_date'?new Date(cy.start_at).toISOString().slice(0,10):cy[name];
   if(type==='duration')formHtml+=`<label>${label}<select name="${name}">${[9,12].map(n=>`<option value="${n}" ${Number(val)===n?'selected':''}>${n} mois</option>`).join('')}</select></label>`;
   else if(type==='weekday')formHtml+=`<label>${label}<select name="${name}">${['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'].map((d,i)=>`<option value="${i}" ${Number(val)===i?'selected':''}>${d}</option>`).join('')}</select></label>`;
   else if(type==='frequency')formHtml+=`<label>${label}<select name="${name}"><option value="7" ${Number(val)===7?'selected':''}>Chaque semaine</option><option value="14" ${Number(val)===14?'selected':''}>Toutes les deux semaines</option></select></label>`;
   else if(type==='readonly')formHtml+=`<label>${label}<input name="${name}" readonly value="${escape(cy.end_date||'')}"></label>`;
   else formHtml+=`<label>${label}<input name="${name}" type="${type}" value="${escape(val??'')}" ${type==='number'?'min="0" step="1"':''} required></label>`;
  }
  openModal('Modifier le cycle',`<p class="hint">Les règles financières et le calendrier ne peuvent plus changer après l'enregistrement de mouvements. Le nom peut être corrigé.</p><form id="editCycleForm">${formHtml}<button class="primary full">Enregistrer les modifications</button></form>`);
  const form=$('#editCycleForm');
  const update=()=>{const start=form.elements.start_date.value,months=Number(form.elements.duration_months.value);if(!start)return;const [y,m,d]=start.split('-').map(Number),first=new Date(Date.UTC(y,m-1+months,1)),last=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();form.elements.end_date_preview.value=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth(),Math.min(d,last))).toISOString().slice(0,10)};
  form.elements.start_date.onchange=update;form.elements.duration_months.onchange=update;
  form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button.primary');b.disabled=true;try{await req('/api/save',{section:'cycle_update',data:{...Object.fromEntries(new FormData(form)),cycle_id:cycleId}});closeModal();toast('Cycle modifié avec succès');await show('cycles',{force:true})}catch(err){toast(err.message);b.disabled=false}};
 }catch(err){toast(err.message)}
}
