async function closeCycle(cycle_id){openModal('Clôturer définitivement le cycle',`<p class="hint">Cette action interdit tout nouveau mouvement sur ce cycle. Les crédits doivent être intégralement remboursés.</p><form id="closeCycleForm"><label>Mot de passe de l’administrateur<div class="password-wrap"><input name="password" id="closeCyclePassword" type="password" required><button type="button" class="eye" data-eye="closeCyclePassword">◉</button></div></label><button class="primary full">Confirmer la clôture</button></form>`);$('#closeCycleForm').onsubmit=async e=>{e.preventDefault();try{await req('/api/save',{section:'cycle_close',data:{cycle_id,password:e.target.elements.password.value}});closeModal();toast('Cycle clôturé');await show('cycles',{force:true})}catch(err){toast(err.message)}}}
function localToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Abidjan',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
async function renderCalendar(s){
 $('#view').innerHTML='<div class="card">Chargement du calendrier des réunions et épargnes…</div>';
 try{
  const rows=(await req('/api/load?section=cycles')).data;
  const cy=rows.find(c=>c.status==='active')||rows[0];
  if(!cy){$('#view').innerHTML='<div class="card">Ouvrez un cycle pour afficher les réunions et cotisations.</div>';return;}
  const start=new Date(cy.start_at),fallback=new Date(start);
  fallback.setUTCMonth(fallback.getUTCMonth()+Number(cy.duration_months||12));
  const end=new Date((cy.end_date||fallback.toISOString().slice(0,10))+'T00:00:00Z');
  const dates=[];let day=new Date(start);
  day.setUTCDate(day.getUTCDate()+(Number(cy.weekday)-day.getUTCDay()+7)%7);
  while(day<end&&dates.length<65){dates.push(day.toISOString().slice(0,10));day.setUTCDate(day.getUTCDate()+Number(cy.frequency_days||7));}
  const today=localToday(),closed=cy.status==='closed';
  // Une seule requête agrégée pour toutes les dates : pas de chargement par ligne.
  const unpaidRows=(await req('/api/load?section=meeting_unpaid_dates&cycle_id='+encodeURIComponent(cy.id))).data;
  const unpaidDates=new Set(unpaidRows.map(r=>r.meeting_date));
  $('#view').innerHTML=`<div class="card"><h3>${escape(cy.name)} — Réunions et épargnes</h3><p>Du ${new Date(cy.start_at).toLocaleDateString('fr-FR')} au ${escape(cy.end_date||fallback.toISOString().slice(0,10))} · ${cy.frequency_days===14?'Toutes les deux semaines':'Chaque semaine'} · ${closed?'Clôturé':'Actif'}</p><div class="table-wrap"><table><thead><tr><th>Date prévue</th><th>État</th><th>Action</th></tr></thead><tbody>${dates.map(d=>{const future=d>today,hasUnpaid=unpaidDates.has(d);return `<tr class="${future?'future-date':''}"><td>${new Date(d+'T12:00:00Z').toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}</td><td>${future?'À venir · Verrouillée':closed?'Cycle clôturé · Consultation':'Disponible'}</td><td><button class="secondary ${hasUnpaid?'meeting-unpaid':''}" data-reunion="${d}" ${future?'disabled title="Date future : accès verrouillé"':''}>${future?'Verrouillée':hasUnpaid?'Gérer la réunion et les parts · Impayés':'Gérer la réunion et les parts'}</button></td></tr>`}).join('')}</tbody></table></div></div>`;
  document.querySelectorAll('[data-reunion]:not([disabled])').forEach(btn=>btn.onclick=()=>openMeetingDay('meetings',cy,btn.dataset.reunion));
 }catch(e){$('#view').innerHTML=`<div class="card hint">${escape(e.message)}</div>`;}
}
function updateFineHighlight(tr,cy){const due=tr.querySelector('.presence').value==='0'&&tr.querySelector('.finepaid').value==='0'&&Number(cy.absence_fine)>0;tr.querySelector('.fine').classList.toggle('debt-due',due);tr.querySelector('.finepaid').closest('td').classList.toggle('debt-due',due);}
async function openMeetingDay(s,cy,date){
 try{
  if(date>localToday())return toast('Les réunions futures sont verrouillées');
  const detail=(await req('/api/load?section=meeting_detail&cycle_id='+encodeURIComponent(cy.id)+'&date='+encodeURIComponent(date))).data;
  const attendance=new Map(detail.attendance.map(r=>[r.member_id,r]));
  const savings=new Map(detail.savings.map(r=>[r.member_id,r]));
  const locked=cy.status==='closed';
  openModal('Réunion et épargne — '+date,`<p>${escape(cy.name)} · ${escape(date)} ${locked?'· Cycle clôturé (lecture seule)':''}</p><div class="table-wrap date-detail"><table><thead><tr><th>Membre</th><th>Présence</th><th>Amende</th><th>Paiement</th><th>Nombre de parts</th><th>Montant calculé</th></tr></thead><tbody>${detail.members.map(m=>{const a=attendance.get(m.id),v=savings.get(m.id);return `<tr data-line="${escape(m.id)}" data-had-attendance="${a?'1':'0'}"><td data-label="Membre">${escape(m.name)}</td><td data-label="Présence"><select class="presence" ${locked?'disabled':''}><option value="">Non pointé</option><option value="1" ${a?.present===1?'selected':''}>Présent</option><option value="0" ${a?.present===0?'selected':''}>Absent</option></select></td><td data-label="Amende" class="fine ${a?.present===0&&!a.fine_paid&&Number(a.fine_amount)>0?'debt-due':''}">${a?.present===0?money(a.fine_amount):'—'}</td><td data-label="Paiement" class="${a?.present===0&&!a.fine_paid&&Number(a.fine_amount)>0?'debt-due':''}"><select class="finepaid" ${locked?'disabled':''}><option value="present">Présent</option><option value="0" ${!a?.fine_paid?'selected':''}>Non payée</option><option value="1" ${a?.fine_paid?'selected':''}>Payée</option></select></td><td data-label="Nombre de parts"><input type="number" class="savingparts" min="1" max="100000" step="1" inputmode="numeric" ${v||locked?'disabled':''} value="${v?.shares||''}" placeholder="Parts"></td><td data-label="Montant calculé" class="amount-preview">${v?money(v.amount):'0 FCFA'}</td></tr>`}).join('')}</tbody></table></div><p class="muted">Valeur d'une part : ${money(cy.share_value)}. Amende d'absence : ${money(cy.absence_fine)}. Les amendes non payées restent dues et ne sont pas incluses dans les bénéfices encaissés.</p>${locked?'':'<div class="global-save-footer"><span id="saveInfo" class="muted">Enregistrez toutes les modifications en une seule fois.</span><button id="saveMeetingAll" class="primary">Enregistrer</button></div>'}`);
  $('#modal .modal').classList.add('wide-detail');
  document.querySelectorAll('#modalBody tr[data-line]').forEach(tr=>{
   const presence=tr.querySelector('.presence'),parts=tr.querySelector('.savingparts');
   const payment=tr.querySelector('.finepaid');
   const syncPayment=()=>{
    tr.querySelector('.fine').textContent=presence.value==='0'?money(cy.absence_fine):'—';
    if(presence.value==='1') {payment.value='present';payment.disabled=true;}
    else if(presence.value==='0') {if(payment.value==='present')payment.value='0';payment.disabled=locked;}
    else {payment.value='present';payment.disabled=true;}
    updateFineHighlight(tr,cy);
   };
   presence.onchange=syncPayment;
   syncPayment();
   tr.querySelector('.finepaid').onchange=()=>updateFineHighlight(tr,cy);
   if(parts)parts.oninput=()=>{const n=Number(parts.value);tr.querySelector('.amount-preview').textContent=Number.isSafeInteger(n)&&n>0?money(n*cy.share_value):'0 FCFA';};
  });
  const button=$('#saveMeetingAll');
  if(button)button.onclick=async()=>{
   const rows=[];
   for(const tr of document.querySelectorAll('#modalBody tr[data-line]')){
    const presence=tr.querySelector('.presence').value,raw=tr.querySelector('.savingparts').value.trim();
    if(raw!==''&&(!/^\d+$/.test(raw)||Number(raw)<1||Number(raw)>100000))return toast('Nombre de parts invalide pour '+tr.querySelector('td').textContent);
    if(presence===''&&raw===''&&tr.dataset.hadAttendance!=='1')continue;
    rows.push({member_id:tr.dataset.line,present:presence===''?null:Number(presence),fine_paid:presence==='0'?Number(tr.querySelector('.finepaid').value):0,shares:tr.querySelector('.savingparts').disabled?0:(raw===''?0:Number(raw))});
   }
   if(!rows.length)return toast('Aucune information à enregistrer');
   button.disabled=true;button.textContent='Enregistrement…';
   try{const r=await req('/api/save',{section:'meeting_bulk',data:{cycle_id:cy.id,meeting_date:date,rows}});toast(`${r.saved_attendance} présence(s) et ${r.saved_savings} cotisation(s) enregistrées`);closeModal();await renderCalendar('meetings');}
   catch(e){toast(e.message);button.disabled=false;button.textContent='Enregistrer';}
  };
 }catch(e){toast(e.message);}
}
function localDate(v){return new Date(v).toISOString().slice(0,10)}
function loanDue(l){let p=Math.max(0,l.principal-(l.paid_principal||0)),i=Math.max(0,l.interest_total-(l.paid_interest||0)),old=Math.max(0,(l.penalty_accrued||0)-(l.paid_penalty||0));let start=Math.max(l.due_at,l.penalty_last_at||l.due_at),end=Date.now(),n=0;if(end>start){if(l.penalty_frequency==='monthly'){let a=new Date(start),b=new Date(end);n=(b.getUTCFullYear()-a.getUTCFullYear())*12+b.getUTCMonth()-a.getUTCMonth()-(b.getUTCDate()<a.getUTCDate()?1:0)}else n=Math.floor((end-start)/86400000)}return {principal:p,interest:i,penalty:old+Math.round((p+i)*Number(l.penalty_percent||0)*Math.max(0,n)/100),total:p+i+old+Math.round((p+i)*Number(l.penalty_percent||0)*Math.max(0,n)/100)}}
async function loanForm(loanId=null){let loans=loanId?(cache.loans||(await req('/api/load?section=loans')).data):[],l=loans.find(x=>x.id===loanId);let members=await options('member'),cycles=await options('cycle');openModal(l?'Modifier le crédit':'Accorder un crédit',`<form id="newLoanForm" class="loan-editor"><div class="loan-identifiers"><label>Cycle<select name="cycle_id" ${l?'disabled':''}>${cycles}</select></label><label>Membre<select name="member_id" ${l?'disabled':''}>${members}</select></label></div><div class="form-grid loan-field-grid"><label>Capital (FCFA)<input name="principal" type="number" min="1" step="1" required value="${l?.principal||''}"></label><label>Intérêt forfaitaire (%)<input name="rate_percent" type="number" min="0" max="100" step=".01" required value="${l?.rate_percent??10}"></label><label>Durée du prêt (jours)<input name="term_days" type="number" min="1" max="1095" required value="${l?.term_days||30}"></label><label>Date de décaissement<input name="disbursement_date" type="date" required value="${localDate(l?.disbursed_at||Date.now())}"></label><label>Type de remboursement<select name="repayment_frequency"><option value="weekly">Par semaine</option><option value="monthly">Par mois</option></select></label><label>Pénalité (%)<input name="penalty_percent" type="number" min="0" max="100" step=".01" required value="${l?.penalty_percent||0}"></label><label>Fréquence pénalité<select name="penalty_frequency"><option value="daily">Par jour</option><option value="monthly">Par mois</option></select></label></div><p id="loanEstimate" class="hint loan-estimate"></p><div class="loan-actionbar"><span>Les montants sont vérifiés lors de l’enregistrement.</span><button class="primary" type="submit">Enregistrer le crédit</button></div></form>`);$('#modal .modal').classList.add('loan-dialog');let f=$('#newLoanForm');if(l){f.elements.cycle_id.value=l.cycle_id;f.elements.member_id.value=l.member_id;f.elements.repayment_frequency.value=l.repayment_frequency||'monthly';f.elements.penalty_frequency.value=l.penalty_frequency||'daily'}let calc=()=>{let capital=Number(f.elements.principal.value),rate=Number(f.elements.rate_percent.value),days=Number(f.elements.term_days.value),freq=f.elements.repayment_frequency.value;let n=freq==='weekly'?Math.ceil(days/7):Math.ceil(days/30);$('#loanEstimate').textContent=`Total hors pénalités : ${money(Math.round(capital*(1+rate/100)))} · ${n||0} échéances · Environ ${money(n?Math.ceil(capital*(1+rate/100)/n):0)} par ${freq==='weekly'?'semaine':'mois'}. Montant indicatif : dernière échéance ajustée.`};f.oninput=calc;f.onchange=calc;calc();f.onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(f));if(l)data.loan_id=l.id;let btn=f.querySelector('[type=submit]');btn.disabled=true;try{await req('/api/save',{section:l?'loan_update':'loan',data});closeModal();toast('Crédit enregistré');show('loans',{force:true})}catch(er){toast(er.message);btn.disabled=false}}}
async function loanReport(id){let l=(cache.loans||(await req('/api/load?section=loans')).data).find(x=>x.id===id);if(!l)return;let history=(await req('/api/load?section=loan_history&loan_id='+encodeURIComponent(id))).data;let s=history.situation,date=v=>localDate(v);openModal('Situation détaillée du crédit',`<div id="loanPrintable" class="loan-report"><div class="loan-report-header"><div><small>AVEC MANAGER PRO · RAPPORT FINANCIER</small><h3>${escape(l.member_name)}</h3></div><span class="loan-report-mark">AVEC</span></div><p>Capital : ${money(l.principal)} · Intérêts : ${money(l.interest_total)} · Total initial : ${money(l.principal+l.interest_total)}</p><p>Décaissement : ${date(l.disbursed_at||l.created_at)} · Échéance : ${date(l.due_at)} · Durée : ${l.term_days} jours</p><p>Remboursement : ${l.repayment_frequency==='weekly'?'Hebdomadaire':'Mensuel'} · Pénalité : ${l.penalty_percent||0}% ${l.penalty_frequency==='monthly'?'par mois':'par jour'}</p><p>Déjà réglé : ${money(l.paid)} · Capital dû : ${money(s.principal)} · Intérêts dus : ${money(s.interest)} · Pénalités exigibles estimées : ${money(s.penalty)}</p><h3>Restant dû estimé : ${money(s.total)}</h3><h3>Historique des règlements</h3><div class="table-wrap loan-report-table"><table><tr><th>Date</th><th>Total</th><th>Capital</th><th>Intérêts</th><th>Pénalités</th></tr>${history.payments.map(r=>`<tr><td>${date(r.created_at)}</td><td>${money(r.amount)}</td><td>${money(r.principal_amount)}</td><td>${money(r.interest_amount)}</td><td>${money(r.penalty_amount)}</td></tr>`).join('')}</table></div><p class="muted">Les pénalités sont recalculées au moment du paiement, selon les dates enregistrées.</p></div><button id="printLoan" class="primary full">Imprimer / Enregistrer en PDF</button>`);$('#modal .modal').classList.add('loan-dialog','loan-report-dialog');$('#printLoan').onclick=()=>{let content=$('#loanPrintable').innerHTML,win=window.open('','_blank');if(!win)return toast('Autorisez la fenêtre d’impression');win.document.write(`<html lang="fr"><head><meta charset="utf-8"><title>Situation du crédit</title><style>@page{size:A4 portrait;margin:13mm}body{font:11px Arial,sans-serif;color:#143b30;margin:0}h3{font-size:15px;color:#07553f;margin:13px 0 8px}p{margin:7px 0;line-height:1.45}.loan-report-header{display:flex;justify-content:space-between;align-items:center;padding-bottom:12px;border-bottom:3px solid #cda133}.loan-report-header small{font-size:10px;color:#a47a17}.loan-report-mark{font-size:21px;font-weight:900;color:#07553f}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:10px}th,td{border:1px solid #d9e3de;padding:7px 5px;overflow-wrap:anywhere;text-align:left}th{background:#e7f2eb;color:#063d2f}.table-wrap{overflow:visible}.muted{color:#68766f}tr{page-break-inside:avoid}</style></head><body>${content}<script>window.onload=()=>{window.focus();window.print()}<\/script></body></html>`);win.document.close()}}
async function loanDelete(id){openModal('Supprimer le crédit',`<div class="hint">La suppression est interdite après tout remboursement. Saisissez votre mot de passe administrateur.</div><form id="loanDeleteForm"><label>Mot de passe<div class="password-wrap"><input id="loanDeletePassword" name="password" type="password" required><button class="eye" type="button" data-eye="loanDeletePassword">◉</button></div></label><label><input type="checkbox" name="confirm" required> Confirmer la suppression</label><button class="primary danger full">Supprimer</button></form>`);wireEyes();$('#loanDeleteForm').onsubmit=async e=>{e.preventDefault();try{await req('/api/save',{section:'loan_delete',data:{loan_id:id,password:e.target.elements.password.value,confirm:e.target.elements.confirm.checked}});closeModal();show('loans',{force:true})}catch(er){toast(er.message)}}}
async function repaymentForm(){let loans=(await req('/api/load?section=loans')).data.filter(l=>l.status==='active'),opts=loans.map(l=>`<option value="${escape(l.id)}">${escape(l.member_name)} · ${money(l.principal)}</option>`).join('');openModal('Remboursement',`<form id="repayForm"><label>Crédit<select name="loan_id" required>${opts}</select></label><label>Type de remboursement<select name="repayment_type"><option value="partial">Partiel</option><option value="total">Total</option></select></label><label>Date de paiement<input type="date" name="payment_date" required value="${localDate(Date.now())}"></label><label id="receivedWrap">Montant reçu<input name="amount" type="number" min="1" step="1"></label><div id="remainingPreview" class="hint"></div><button type="submit" class="primary full">Enregistrer</button></form>`);let f=$('#repayForm');let calc=()=>{let l=loans.find(x=>x.id===f.elements.loan_id.value);if(!l)return;let v=loanDue(l),total=f.elements.repayment_type.value==='total',received=total?v.total:Number(f.elements.amount.value||0);$('#receivedWrap').hidden=total;$('#remainingPreview').innerHTML=`<strong>Total restant dû : ${money(v.total)}</strong><br>${total?'Règlement total : '+money(v.total):'Reste estimé après règlement : '+money(Math.max(0,v.total-received))}`};f.oninput=calc;f.onchange=calc;calc();f.onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(f)),b=f.querySelector('[type=submit]');b.disabled=true;try{await req('/api/save',{section:'repayment',data});closeModal();toast('Remboursement enregistré');show('repayments',{force:true})}catch(er){toast(er.message);b.disabled=false}}}
function settings(){$('#view').innerHTML=`<div class="card"><h3>Changer mon mot de passe</h3><form id="passForm"><div class="form-grid"><label>Mot de passe actuel<div class="password-wrap"><input id="oldPass" type="password" required><button type="button" class="eye" data-eye="oldPass">◉</button></div></label><label>Nouveau mot de passe (12 caractères minimum)<div class="password-wrap"><input id="newPass" type="password" minlength="12" required><button type="button" class="eye" data-eye="newPass">◉</button></div></label></div><button class="primary">Changer le mot de passe</button></form></div><h3>Formules disponibles</h3><div class="plans"><div class="plan"><h3>GRATUIT</h3><div class="price">0 FCFA</div><p>10 jours · Accès complet</p><small>Activation initiale ou par Super Admin</small></div><div class="plan"><h3>STANDARD</h3><div class="price">2 600 FCFA</div><p>30 jours · Accès complet</p><a href="https://pay.wave.com/m/M_ci_Enx-2JNAklk-/c/ci/?amount=2600" target="_blank" rel="noopener" class="primary" style="display:inline-block;text-decoration:none">Payer avec Wave</a></div><div class="plan"><h3>PROFESSIONNEL</h3><div class="price">25 600 FCFA</div><p>365 jours · Accès complet</p><a href="https://pay.wave.com/m/M_ci_Enx-2JNAklk-/c/ci/?amount=25600" target="_blank" rel="noopener" class="primary" style="display:inline-block;text-decoration:none">Payer avec Wave</a></div></div><p class="muted">Un paiement Wave ne modifie pas automatiquement le forfait : activation par le Super Admin après vérification. Aucun justificatif transmis automatiquement.</p>`;wireEyes();$('#passForm').onsubmit=async e=>{e.preventDefault();try{await req('/api/change-password',{oldPassword:$('#oldPass').value,newPassword:$('#newPass').value});toast('Mot de passe mis à jour, reconnectez-vous');setTimeout(()=>location.reload(),1200)}catch(er){toast(er.message)}}}
function promo(){lastPromo=Date.now();openModal('Passez à la formule Professionnelle',`<p>Profitez de la formule Professionnelle avec <strong>365 jours d'accès complet</strong> à la gestion de votre AVEC.</p><div class="hint">Professionnel : <strong>25 600 FCFA / 365 jours</strong></div><div class="row"><button class="secondary" id="understood">Compris</button><button class="primary" id="toPlans">Acheter ma formule Professionnelle</button></div>`);$('#understood').onclick=closeModal;$('#toPlans').onclick=()=>{closeModal();show('settings')}}

// Gestion des motifs et cotisations solidaires. Aucun chargement des autres sections.
let solidarityTab='motifs';
function solidPeriods(m){let dates=[],d=new Date(m.start_date+'T12:00:00Z'),end=new Date(m.end_date+'T12:00:00Z');for(let i=0;i<240&&d<=end;i++){dates.push(d.toISOString().slice(0,10));if(m.frequency==='weekly')d.setUTCDate(d.getUTCDate()+7);else{let day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);let last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));}}return dates;}
function solidDues(m,persons,payments){const elapsed=solidPeriods(m).filter(d=>d<=new Date().toISOString().slice(0,10)).length;const expected=elapsed*Number(m.contribution)*persons.length;const paid=payments.filter(x=>x.motif_id===m.id).reduce((a,x)=>a+Number(x.paid||0),0);return {expected,paid,remaining:Math.max(0,expected-paid),progress:expected?Math.min(100,Math.round(100*paid/expected)):0};}
function expenseList(rows){
 $('#view').innerHTML=`<div class="card"><div class="toolbar"><h3>Liste des dépenses (${rows.length})</h3><button class="primary" id="addExpense">+ Ajouter une dépense</button></div><div class="table-wrap expenses-table"><table><thead><tr><th>Description</th><th>Montant</th><th>Date</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td data-label="Description">${escape(r.description)}</td><td data-label="Montant">${money(r.amount)}</td><td data-label="Date">${new Date(r.created_at).toLocaleDateString('fr-FR')}</td><td data-label="Actions" class="expense-actions"><button class="secondary" data-exp-edit="${r.id}">Modifier</button> <button class="secondary danger" data-exp-delete="${r.id}">Supprimer</button></td></tr>`).join('')}</tbody></table></div></div>`;
 $('#addExpense').onclick=()=>makeForm('expenses');
 function edit(row,del){openModal(del?'Supprimer une dépense':'Modifier une dépense',`<form id="expenseAction"><p class="muted">${del?'Confirmer la suppression de cette dépense.':'Corriger les informations de la dépense.'}</p>${del?'':`<label>Description<input name="description" required value="${escape(row.description)}"></label><label>Montant (FCFA)<input name="amount" type="number" min="1" required value="${row.amount}"></label>`}<label>Mot de passe administrateur<div class="password-wrap"><input name="password" id="expensePassword" type="password" required><button class="eye" type="button" data-eye="expensePassword">◉</button></div></label><button class="primary full ${del?'danger':''}">${del?'Supprimer':'Enregistrer'}</button></form>`);wireEyes();$('#expenseAction').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{await req('/api/save',{section:del?'expense_delete':'expense_update',data:{...values,id:row.id}});closeModal();toast('Opération enregistrée');show('expenses',{force:true})}catch(err){toast(err.message)}}}
 document.querySelectorAll('[data-exp-edit]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.expEdit),false));document.querySelectorAll('[data-exp-delete]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.expDelete),true));
}
async function solidarityDashboard(){
 const ticket=requestSerial;$('#view').innerHTML='<div class="card">Chargement de la solidarité…</div>';
 try{let [a,b]=await Promise.all([req('/api/load?section=solidarity_motifs'),req('/api/load?section=solidarity_contributions')]);if(ticket!==requestSerial)return;
 const data=a.data,items=b.data,motifs=data.motifs,members=data.members.filter(x=>x.active),payments=data.payments;
 const dates=m=>`${escape(m.start_date)} au ${escape(m.end_date)}`;
 const actions=(m)=>me.role==='admin'?`<button class="secondary" data-solid-edit="${m.id}">Modifier</button> <button class="secondary danger" data-solid-delete="${m.id}">Supprimer</button>`:'';
 const tabs=[['motifs','Motifs de solidarité'],['mouvements','Mouvements des cotisations'],['resume','Résumé des cotisations']];
 $('#view').innerHTML=`<div class="card"><div class="solid-nav">${tabs.map(([id,label])=>`<button class="secondary ${solidarityTab===id?'solid-active':''}" data-solid-tab="${id}">${label}</button>`).join('')}</div><div id="solidContent"></div></div>`;
 function render(){const root=$('#solidContent');if(solidarityTab==='motifs'){
 root.innerHTML=`<div class="toolbar"><h3>Motifs de solidarité</h3><button class="primary" id="solidAddMotif">+ Créer un motif</button></div><label class="solid-filter">Rechercher par numéro, destination ou membre <input id="solidMotifFilter" type="search" placeholder="Numéro, destination, membre…"></label><div class="table-wrap solid-table"><table><thead><tr>${['N° motif','Motif','Participation','Destination','Bénéficiaire','Fréquence','Période','Statut','Actions'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${motifs.map(m=>`<tr class="solid-click" data-report="${m.id}"><td data-label="N° motif">${escape(m.reference||m.id.slice(0,8))}</td><td data-label="Motif">${escape(m.title)}</td><td data-label="Participation">${money(m.contribution)}</td><td data-label="Destination">${m.destination==='member'?'Membre':'Évènement commun'}</td><td data-label="Bénéficiaire">${escape(m.beneficiary_name||'—')}</td><td data-label="Fréquence">${m.frequency==='weekly'?'Hebdomadaire':'Mensuelle'}</td><td data-label="Période">${dates(m)}</td><td data-label="Statut">${m.status==='closed'?'Clôturé':'Actif'}</td><td data-label="Actions" class="solid-actions">${actions(m)}</td></tr>`).join('')}</tbody></table></div>`;
 $('#solidAddMotif').onclick=()=>motifForm();$('#solidMotifFilter').oninput=e=>{let q=e.target.value.toLocaleLowerCase('fr');root.querySelectorAll('tr[data-report]').forEach(tr=>{const m=motifs.find(x=>x.id===tr.dataset.report);tr.hidden=!([m?.reference,m?.destination==='member'?'membre':'évènement commun',m?.beneficiary_name,m?.title].join(' ').toLocaleLowerCase('fr').includes(q));});};root.querySelectorAll('[data-solid-edit]').forEach(x=>x.onclick=e=>{e.stopPropagation();motifForm(motifs.find(m=>m.id===x.dataset.solidEdit))});root.querySelectorAll('[data-solid-delete]').forEach(x=>x.onclick=e=>{e.stopPropagation();solidConfirm('solidarity_motif_delete',x.dataset.solidDelete,'Supprimer ce motif ?')});root.querySelectorAll('[data-report]').forEach(x=>x.onclick=()=>solidReport(x.dataset.report));
 }else if(solidarityTab==='mouvements'){
 root.innerHTML=`<div class="toolbar"><h3>Mouvements des cotisations</h3><button class="primary" id="solidAddMovement">+ Créer un mouvement</button></div><label class="solid-filter">Rechercher par numéro de mouvement ou montant <input id="solidMovementFilter" type="search" placeholder="Numéro ou montant…"></label><div class="table-wrap solid-table"><table><thead><tr>${['N° mouvement','Date','Membre','Motif','Montant versé','Mode','Actions'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${items.map(x=>`<tr data-movement-row="${x.id}"><td data-label="N° mouvement">${escape(x.reference||x.id.slice(0,8))}</td><td data-label="Date">${escape(x.payment_date)}</td><td data-label="Membre">${escape(x.member_name)}</td><td data-label="Motif">${escape(x.motif_name)}</td><td data-label="Montant versé">${money(x.amount)}</td><td data-label="Mode">Versement</td><td data-label="Actions" class="solid-actions"><button class="secondary" data-solid-medit="${x.id}">Modifier</button> <button class="secondary danger" data-solid-mdelete="${x.id}">Supprimer</button></td></tr>`).join('')}</tbody></table></div>`;
 $('#solidAddMovement').onclick=()=>movementForm();$('#solidMovementFilter').oninput=e=>{let q=e.target.value.toLocaleLowerCase('fr').replace(/\s/g,'');root.querySelectorAll('[data-movement-row]').forEach(tr=>{let m=items.find(x=>x.id===tr.dataset.movementRow);tr.hidden=!((m?.reference||m?.id||'').toLocaleLowerCase('fr').includes(q)||String(m?.amount||'').includes(q));});};root.querySelectorAll('[data-solid-medit]').forEach(x=>x.onclick=()=>movementForm(items.find(i=>i.id===x.dataset.solidMedit)));root.querySelectorAll('[data-solid-mdelete]').forEach(x=>x.onclick=()=>solidConfirm('solidarity_contribution_delete',x.dataset.solidMdelete,'Supprimer ce mouvement ?'));
 }else{
 root.innerHTML=`<div class="toolbar"><h3>Résumé des cotisations</h3></div><div class="table-wrap solid-table"><table><thead><tr>${['Motif','Prévu à ce jour','Encaissé','Reste à encaisser','Progression','Statut / Actions'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${motifs.map(m=>{let d=solidDues(m,members,payments);let totalExpected=solidPeriods(m).length*Number(m.contribution)*members.length;let incomplete=d.paid<totalExpected;return `<tr ${d.remaining>0&&m.status==='active'?`class="solid-due-row" data-due-motif="${m.id}" tabindex="0" role="button" aria-label="Régulariser les impayés du motif ${escape(m.title)}"`:''}><td data-label="Motif">${escape(m.title)}</td><td data-label="Prévu">${money(d.expected)}</td><td data-label="Encaissé">${money(d.paid)}</td><td data-label="Reste à encaisser"><span class="${d.remaining?'debt-due':''}">${money(d.remaining)}</span></td><td data-label="Progression"><progress max="100" value="${d.progress}"></progress> ${d.progress}%</td><td data-label="Actions"><div class="solid-buttons"><button class="secondary" data-report="${m.id}">Rapport</button>${m.status==='active'&&me.role==='admin'?`<button class="primary" data-withdraw="${m.id}" ${incomplete?'disabled title="Cotisations incomplètes"':''}>Retrait des fonds</button>`:`<span class="pill">Clôturé</span>${m.status==='closed'&&me.role==='admin'?`<button type="button" class="secondary danger" data-delete-closed="${m.id}">Supprimer</button>`:''}`}</div></td></tr>`}).join('')}</tbody></table></div>`;
 root.querySelectorAll('[data-report]').forEach(x=>x.onclick=e=>{e.stopPropagation();solidReport(x.dataset.report)});root.querySelectorAll('[data-withdraw]').forEach(x=>x.onclick=e=>{e.stopPropagation();solidConfirm('solidarity_motif_withdraw',x.dataset.withdraw,'Clôturer ce motif et enregistrer le retrait de tous les fonds encaissés ?',true)});
 root.querySelectorAll('[data-delete-closed]').forEach(x=>x.onclick=e=>{e.stopPropagation();const m=motifs.find(y=>y.id===x.dataset.deleteClosed);if(m)deleteClosedMotif(m)});
 root.querySelectorAll('[data-due-motif]').forEach(x=>{x.onclick=e=>{if(e.target.closest('button'))return;regularizeMotif(x.dataset.dueMotif)};x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();regularizeMotif(x.dataset.dueMotif)}}});
 }}
 function deleteClosedMotif(m){
  openModal('Supprimer définitivement le motif clôturé',`<p class="hint"><strong>ATTENTION :</strong> cette suppression est irréversible. Le motif <strong>${escape(m.title)}</strong> (${escape(m.reference||'')}) et tous ses mouvements de cotisation seront effacés. Les fonds déjà retirés ne seront pas remboursés ni rétablis automatiquement. Effectuez une sauvegarde D1 préalable.</p><form id="deleteClosedMotifForm"><label>Recopiez le numéro du motif<input name="reference_confirmation" required autocomplete="off" placeholder="${escape(m.reference||'')}"></label>${passwordMarkup()}<label><input type="checkbox" name="confirm" required> Je confirme la suppression définitive du motif clôturé et de ses mouvements.</label><button class="primary danger full" type="submit">Supprimer définitivement</button></form>`);
  wireEyes();const f=$('#deleteClosedMotifForm');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button[type="submit"]');b.disabled=true;try{await req('/api/save',{section:'solidarity_motif_delete_closed',data:{motif_id:m.id,password:$('#solidPwd').value,reference_confirmation:f.elements.reference_confirmation.value.trim(),confirm:f.elements.confirm.checked}});closeModal();toast('Motif clôturé et mouvements supprimés');await solidarityDashboard()}catch(err){toast(err.message);b.disabled=false}};
 }
 async function regularizeMotif(id){
  const motif=motifs.find(m=>m.id===id);if(!motif)return;
  const elapsed=solidPeriods(motif).filter(d=>d<=new Date().toISOString().slice(0,10)).length;
  const dues=members.map(member=>{const expected=elapsed*Number(motif.contribution);const paid=Number(payments.find(x=>x.motif_id===id&&x.member_id===member.id)?.paid||0);return {member,expected,paid,remaining:Math.max(0,expected-paid)}}).filter(x=>x.remaining>0);
  if(!dues.length){toast('Ce motif ne comporte plus d’impayés');return;}
  const rows=dues.map(({member,paid,remaining})=>`<tr><td data-label="Membre">${escape(member.name)}</td><td data-label="Versé">${money(paid)}</td><td data-label="Reste dû" class="debt-due">${money(remaining)}</td><td data-label="Règlement"><button type="button" class="primary" data-regularize="${member.id}">Régler</button></td></tr>`).join('');
  openModal('Cotisations impayées — '+motif.title,`<p class="muted">Motif N° ${escape(motif.reference||'')} · ${dues.length} membre(s) à régulariser. Les versements après échéance restent autorisés tant que le cycle est ouvert.</p><div class="table-wrap solid-table"><table><thead><tr><th>Membre</th><th>Déjà versé</th><th>Reste à payer</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div>`);
  document.querySelectorAll('[data-regularize]').forEach(btn=>btn.onclick=()=>{
   const d=dues.find(x=>x.member.id===btn.dataset.regularize);if(!d)return;
   openModal('Régler la cotisation — '+d.member.name,`<form id="regularizeForm"><p>Motif : <strong>${escape(motif.title)}</strong> (${escape(motif.reference||'')})</p><p class="debt-due">Reste exigible : <strong>${money(d.remaining)}</strong></p><label>Date du paiement<input name="payment_date" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><label>Type de paiement<select id="regularizeType"><option value="total">Total</option><option value="partial">Partiel</option></select></label><label>Montant reçu (FCFA)<input id="regularizeAmount" name="amount" type="number" min="1" max="${d.remaining}" required value="${d.remaining}"></label><button class="primary full" type="submit">Enregistrer le règlement</button></form>`);
   const form=$('#regularizeForm'), amount=$('#regularizeAmount');$('#regularizeType').onchange=e=>{amount.readOnly=e.target.value==='total';if(e.target.value==='total')amount.value=d.remaining};amount.readOnly=true;
   form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;try{await req('/api/save',{section:'solidarity_contribution_create',data:{motif_id:id,member_id:d.member.id,payment_date:form.elements.payment_date.value,amount:Number(amount.value)}});closeModal();toast('Cotisation enregistrée');await solidarityDashboard()}catch(err){toast(err.message);button.disabled=false}};
  });
 }
 async function send(section,data){await req('/api/save',{section,data});closeModal();toast('Enregistrement effectué');await solidarityDashboard()}
 function passwordMarkup(){return `<label>Mot de passe administrateur<div class="password-wrap"><input id="solidPwd" type="password" required><button type="button" class="eye" data-eye="solidPwd">◉</button></div></label>`}
 function solidConfirm(action,id,title,confirm=false){openModal(title,`<form id="solidConfirm"><p class="hint">Cette opération sera enregistrée dans le journal. Les fonds déjà retirés ne peuvent pas être effacés.</p>${passwordMarkup()}<button class="primary danger full">Confirmer</button></form>`);wireEyes();$('#solidConfirm').onsubmit=async e=>{e.preventDefault();try{await send(action,{id,motif_id:id,password:$('#solidPwd').value,confirm})}catch(ex){toast(ex.message)}}}
 function motifForm(m){const cycles=data.cycles.filter(c=>c.status==='active');openModal(m?'Modifier le motif':'Créer un motif de solidarité',`<form id="solidMotifForm" class="form-grid"><label>Motif<input name="title" required value="${escape(m?.title||'')}"></label><label>Montant de participation (FCFA)<input name="contribution" type="number" min="1" required value="${m?.contribution||''}"></label><label>Cycle<select name="cycle_id" ${m?'disabled':''}>${cycles.map(c=>`<option value="${c.id}" ${m?.cycle_id===c.id?'selected':''}>${escape(c.name)}</option>`).join('')}</select></label><label>Destination<select name="destination" id="solidDest"><option value="member">À un membre</option><option value="event">À un évènement commun</option></select></label><label id="solidBeneficiary">Membre bénéficiaire<select name="beneficiary_id">${members.map(x=>`<option value="${x.id}">${escape(x.name)}</option>`).join('')}</select></label><label>Fréquence<select name="frequency"><option value="weekly">Chaque semaine</option><option value="monthly">Chaque mois</option></select></label><label>Date de début<input name="start_date" type="date" required value="${m?.start_date||''}"></label><label>Date de fin<input name="end_date" type="date" required value="${m?.end_date||''}"></label>${m?`<div class="wide">${passwordMarkup()}</div>`:''}<button class="primary full wide">Enregistrer</button></form>`);const f=$('#solidMotifForm');f.elements.destination.value=m?.destination||'member';f.elements.frequency.value=m?.frequency||'weekly';if(m?.beneficiary_id)f.elements.beneficiary_id.value=m.beneficiary_id;const sync=()=>{const visible=f.elements.destination.value==='member';$('#solidBeneficiary').hidden=!visible;f.elements.beneficiary_id.disabled=!visible;f.elements.beneficiary_id.required=visible;};f.elements.destination.onchange=sync;sync();wireEyes();f.onsubmit=async e=>{e.preventDefault();let v=Object.fromEntries(new FormData(f));if(m){v.id=m.id;v.password=$('#solidPwd').value;}try{await send(m?'solidarity_motif_update':'solidarity_motif_create',v)}catch(ex){toast(ex.message)}}}
 function movementForm(m){let available=motifs.filter(x=>x.status==='active');openModal(m?'Modifier un mouvement':'Créer un mouvement de solidarité',`<form id="solidMovementForm" class="form-grid"><label>Motif<select name="motif_id" id="solidChosen" ${m?'disabled':''}>${available.map(x=>`<option value="${x.id}">${escape(x.title)}</option>`).join('')}</select></label><label>Membre<select name="member_id" id="solidMember" ${m?'disabled':''}>${members.map(x=>`<option value="${x.id}">${escape(x.name)}</option>`).join('')}</select></label><label>Date de paiement<input type="date" name="payment_date" required value="${m?.payment_date||new Date().toISOString().slice(0,10)}"></label><label>Participation fixée<input id="solidFixed" readonly></label><label>Type de paiement<select id="solidPayType"><option value="partial">Partiel</option><option value="total">Total du restant exigible</option></select></label><label>Montant reçu (FCFA)<input name="amount" id="solidAmount" type="number" min="1" required value="${m?.amount||''}"></label><div class="wide muted" id="solidDueMessage"></div>${m?`<div class="wide">${passwordMarkup()}</div>`:''}<button class="primary full wide">Enregistrer</button></form>`);const f=$('#solidMovementForm');if(m){f.elements.motif_id.value=m.motif_id;f.elements.member_id.value=m.member_id;}let update=()=>{const x=motifs.find(z=>z.id===f.elements.motif_id.value);if(!x)return;let schedule=solidPeriods(x).filter(z=>z<=new Date().toISOString().slice(0,10)).length;let received=payments.find(p=>p.motif_id===x.id&&p.member_id===f.elements.member_id.value)?.paid||0;let remaining=Math.max(0,schedule*x.contribution-received+(m?.amount||0));$('#solidFixed').value=money(x.contribution);$('#solidDueMessage').textContent='Restant exigible : '+money(remaining);if($('#solidPayType').value==='total')$('#solidAmount').value=remaining||x.contribution};['solidChosen','solidMember','solidPayType'].forEach(id=>$('#'+id).onchange=update);if(m)$('#solidPayType').value='partial';update();wireEyes();f.onsubmit=async e=>{e.preventDefault();let v=Object.fromEntries(new FormData(f));if(m){v.id=m.id;v.motif_id=m.motif_id;v.member_id=m.member_id;v.password=$('#solidPwd').value}try{await send(m?'solidarity_contribution_update':'solidarity_contribution_create',v)}catch(ex){toast(ex.message)}}}
 async function solidReport(id){try{const r=(await req('/api/load?section=solidarity_report&motif_id='+encodeURIComponent(id))).data,m=r.motif;let rows=r.contributions;const membersList=members.map(x=>{const paid=rows.filter(z=>z.member_id===x.id).reduce((a,z)=>a+z.amount,0);const expected=solidPeriods(m).filter(z=>z<=new Date().toISOString().slice(0,10)).length*m.contribution;return {...x,paid,remaining:Math.max(0,expected-paid)}});openModal('Rapport détaillé — '+m.title,`<div id="solidPrintable"><h3>${escape(m.title)}</h3><p>Destination : ${m.destination==='member'?'Membre : '+escape(m.beneficiary_name||''):'Évènement commun'} · Cotisation : ${money(m.contribution)} · ${m.frequency==='weekly'?'Hebdomadaire':'Mensuelle'} · ${escape(m.start_date)} au ${escape(m.end_date)}</p><div class="table-wrap"><table><tr><th>Membre</th><th>Encaissé</th><th>Reste exigible</th><th>Situation</th></tr>${membersList.map(x=>`<tr><td>${escape(x.name)}</td><td>${money(x.paid)}</td><td class="${x.remaining?'debt-due':''}">${money(x.remaining)}</td><td>${x.remaining?'Impayé':'À jour'}</td></tr>`).join('')}</table></div><h3>Historique des mouvements</h3><div class="table-wrap"><table><tr><th>Date</th><th>Membre</th><th>Montant</th></tr>${rows.map(x=>`<tr><td>${escape(x.payment_date)}</td><td>${escape(x.member_name)}</td><td>${money(x.amount)}</td></tr>`).join('')}</table></div></div><button id="solidPrint" class="primary full">Imprimer / Enregistrer en PDF</button>`);$('#solidPrint').onclick=()=>{const w=window.open('','_blank');if(!w)return toast('Autorisez les fenêtres contextuelles pour imprimer');w.document.write('<!doctype html><html lang="fr"><meta charset="utf-8"><title>Rapport de solidarité</title><style>body{font:13px Arial;margin:20mm;color:#153d30}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:7px}h3{color:#07533f}@page{size:A4;margin:15mm}</style>'+$('#solidPrintable').innerHTML+'</html>');w.document.close();w.focus();w.print()}}catch(e){toast(e.message)}}
 document.querySelectorAll('[data-solid-tab]').forEach(x=>x.onclick=()=>{solidarityTab=x.dataset.solidTab;document.querySelectorAll('[data-solid-tab]').forEach(y=>y.classList.toggle('solid-active',y===x));render()});render();
 }catch(e){$('#view').innerHTML=`<div class="card hint">${escape(e.message)}. Vérifiez la migration 0004.</div>`}
}

async function reports(){
 const ticket=requestSerial;
 $('#view').innerHTML='<div class="card">Chargement des situations individuelles des membres…</div>';
 try{
  const cycles=(await req('/api/load?section=cycles')).data;
  if(ticket!==requestSerial)return;
  const saved=sessionStorage.getItem('avec-report-cycle')||'';
  const initial=cycles.some(c=>c.id===saved)?saved:'';
  $('#view').innerHTML=`<div class="card"><div class="toolbar"><div><h3>Situation générale des membres</h3><p class="muted">Présences, épargnes, crédits, remboursements, solidarité et solde estimé, par membre.</p></div><div class="report-actions"><label>Cycle <select id="reportCycle"><option value="">Tous les cycles</option>${cycles.map(c=>`<option value="${escape(c.id)}" ${initial===c.id?'selected':''}>${escape(c.name)} (${escape(labelValue(c.status))})</option>`).join('')}</select></label><button class="secondary" id="reportPrint">Imprimer</button><button class="secondary" id="reportCsv">Exporter CSV</button></div></div><div id="reportResult">Chargement du rapport…</div></div>`;
  let current=[];
  const cols=[['code','Numéro'],['name','Nom et prénoms'],['meetings_present','Présences'],['meetings_absent','Absences'],['fines_paid','Amendes payées'],['fines_unpaid','Amendes impayées'],['shares','Parts'],['savings','Épargne'],['credits','Crédits accordés'],['repaid','Remboursé (total)'],['remaining','Reste à rembourser'],['solidarity_paid','Solidarité versée'],['solidarity_received','Aides reçues'],['balance','Solde estimé']];
  const numeric=new Set(['fines_paid','fines_unpaid','savings','credits','repaid','remaining','solidarity_paid','solidarity_received','balance']);
  const reload=async()=>{
    const selected=$('#reportCycle').value;sessionStorage.setItem('avec-report-cycle',selected);
    $('#reportResult').textContent='Actualisation du rapport…';
    try{const result=await req('/api/load?section=member_reports'+(selected?'&cycle_id='+encodeURIComponent(selected):''));if(section!=='reports'||$('#reportCycle')?.value!==selected)return;current=result.data.rows;
      const totals={};for(const [k] of cols)if(k!=='code'&&k!=='name')totals[k]=current.reduce((a,r)=>a+Number(r[k]||0),0);
      const format=(k,value)=>numeric.has(k)?money(value):escape(value);
      const cell=(k,v)=>{const unpaid=(k==='fines_unpaid'||k==='remaining')&&Number(v)>0;const negative=k==='balance'&&Number(v)<0;return `<span class="${unpaid||negative?'debt-due':''}">${unpaid?'À payer : ':''}${format(k,v)}</span>`;};
      $('#reportResult').innerHTML=`<p class="muted">${current.length} membre(s) · Les soldes sont indicatifs et ne constituent pas un montant distribuable.</p><div class="table-wrap report-table"><table><thead><tr>${cols.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${current.map(r=>`<tr>${cols.map(([k,label])=>`<td data-label="${label}">${cell(k,r[k])}</td>`).join('')}</tr>`).join('')}<tr class="report-total">${cols.map(([k],i)=>`<td data-label="Total">${i===0?'TOTAL':i===1?'':cell(k,totals[k]||0)}</td>`).join('')}</tr></tbody></table></div><p class="muted report-legend">Solde estimé = épargne − capital restant − intérêts restant dus − amendes impayées. Les cotisations de solidarité et les aides sont indiquées séparément. Les montants en rouge indiquent les dettes non payées (amendes, reste à rembourser) ou les soldes négatifs. Les bénéfices à répartir ne sont pas inclus. « Remboursé » comprend les remboursements du capital et des intérêts.</p>`;
    }catch(e){$('#reportResult').innerHTML=`<div class="hint">${escape(e.message)}</div>`;}
  };
  $('#reportCycle').onchange=reload;
  $('#reportPrint').onclick=()=>window.print();
  $('#reportCsv').onclick=()=>{const lines=[cols.map(x=>x[1]),...current.map(r=>cols.map(x=>r[x[0]]??''))];const csv='\uFEFF'+lines.map(line=>line.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='situation_membres_avec.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
  await reload();
 }catch(e){if(section==='reports')$('#view').innerHTML=`<div class="card hint">${escape(e.message)}</div>`;}
}
async function partagePage(){
 const ticket=requestSerial;$('#view').innerHTML='<div class="card">Chargement du bilan financier du cycle…</div>';
 try{let cycles=(await req('/api/load?section=cycles')).data;if(ticket!==requestSerial)return;let choice=cycles.find(c=>c.status==='active')||cycles[0];
 $('#view').innerHTML=`<div class="card"><div class="toolbar"><div><h3>Bilan financier du cycle</h3><p class="muted">Situations dues et encaissées, sans double comptabilisation.</p></div><label>Cycle <select id="shareCycle">${cycles.map(c=>`<option value="${escape(c.id)}" ${c.id===choice?.id?'selected':''}>${escape(c.name)}</option>`).join('')}</select></label></div></div><div id="shareContent"></div>`;
 if(!choice){$('#shareContent').innerHTML='<div class="card">Aucun cycle disponible.</div>';return}
 let latest=null;const read=async()=>{const current=$('#shareCycle').value;$('#shareContent').innerHTML='<div class="card">Calcul du bilan en cours…</div>';try{let d=(await req('/api/load?section=partage_bilan&cycle_id='+encodeURIComponent(current))).data;if(section!=='distributions'||$('#shareCycle')?.value!==current)return;latest=d;renderPartage(d)}catch(e){$('#shareContent').innerHTML=`<div class="card hint">${escape(e.message)}</div>`}};$('#shareCycle').onchange=read;await read();
 }catch(e){if(section==='distributions')$('#view').innerHTML=`<div class="card hint">${escape(e.message)}</div>`}}
function renderPartage(d){
 const amount=v=>money(Number(v||0)), row=(name,values)=>`<tr><th>${escape(name)}</th>${values.map(v=>`<td>${typeof v==='string'?escape(v):amount(v)}</td>`).join('')}</tr>`;
 const table=(title,head,rows)=>`<section class="card partage-card"><h3>${escape(title)}</h3><div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${escape(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div></section>`;
 let s=d.savings,a=d.fines,l=d.loans,r=d.recap,sol=d.solidarity;
 let h='';h+=table('Situation générale des épargnes',['Désignation','Parts achetées','Valeur de la part','Valeur des parts','Épargnes encaissées','Épargne en caisse'],[row('TOTAL ÉPARGNES',[s.parts,s.unit,s.value,s.received,s.inCash])]);
 h+=table('Situation générale des amendes d’absence',['Désignation','Absences','Absences sanctionnées','Amende unitaire','Amendes dues','Encaissées','Restant dues'],[row('TOTAL AMENDES',[a.absences,a.count,a.unit,a.due,a.received,a.unpaid])]);
 h+=table('Situation générale des crédits',['Désignation','Crédits','Capital accordé','Intérêts','Capital + intérêts','Remboursé','Reste crédit','Pénalités dues','Pénalités encaissées','Pénalités impayées'],[row('TOTAL CRÉDITS',[l.count,l.principal,l.interest,l.total,l.repaid,l.remaining,l.penaltyDue,l.penaltyReceived,l.penaltyUnpaid])]);
 h+=table('Situation générale des solidarités communes non clôturées',['Référence','Motif','Destination','Membres','Cotisation par période','Total estimé','Encaissé','Non encaissé','Statut'],[...sol.map(x=>row(x.reference,[x.title,x.destination,x.members,x.contribution,x.estimated,x.received,x.unpaid,x.status])),row('TOTAL GÉNÉRAL',['—','—',sol.length?'—':'0','—',sol.reduce((x,y)=>x+y.estimated,0),sol.reduce((x,y)=>x+y.received,0),sol.reduce((x,y)=>x+y.unpaid,0),'—'])]);
 h+=`<section class="card partage-card"><h3>Récapitulatif financier général du cycle</h3><table class="partage-recap"><tbody>${[['Épargnes encaissées',r.savings],['Dépenses du cycle',-r.expenses],['Amendes d’absence dues',r.fines],['Intérêts et pénalités de crédits dus',r.loanYield],['Solidarités communes estimées',r.solidarity],['TOTAL GÉNÉRAL DES VALEURS',r.totalGeneral],['BÉNÉFICE THÉORIQUE NET À RÉPARTIR',r.benefitTheoretical],['Résultat net fondé sur les encaissements',r.benefitReceived]].map(([k,v],i)=>`<tr class="${i>=5?'report-total':''}"><th>${escape(k)}</th><td class="money-right">${amount(v)}</td></tr>`).join('')}</tbody></table><p class="hint">Les montants dus et les solidarités non clôturées constituent ici une estimation théorique suivant la règle demandée. Ils ne sont pas nécessairement disponibles en caisse. Aucun partage réel ne peut être autorisé sur la seule base de ce tableau.</p></section><div class="partage-bottom"><button id="previewShares" class="primary">Prévisualiser le partage</button></div>`;
 $('#shareContent').innerHTML=h;$('#previewShares').onclick=()=>partagePopup(d);
}
function partagePopup(d){const cols=[['code','Code membre'],['name','Nom et prénoms'],['share','Part estimée'],['shares','Parts'],['savings','Épargne'],['meetings','Réunions'],['present','Présences'],['absent','Absences'],['fineDue','Amendes dues'],['finePaid','Amendes réglées'],['fineUnpaid','Amendes impayées'],['loanCount','Crédits'],['loanPrincipal','Capital'],['loanInterest','Intérêts'],['loanRepaid','Remboursé'],['loanRemaining','Crédit restant'],['penaltyUnpaid','Pénalités impayées'],['solidDue','Solidarité due'],['solidPaid','Solidarité réglée'],['solidUnpaid','Solidarité impayée'],['final','Solde final']];let records=[...d.rows];
 openModal('Prévisualisation générale du partage du cycle',`<div class="partage-preview"><p class="hint">Prévisualisation théorique et informative : aucun décaissement et aucune clôture ne seront effectués.</p><div class="toolbar"><label>Rechercher un membre<input id="shareSearch" placeholder="Nom ou numéro"></label><label>Trier par <select id="shareSort"><option value="name">Nom</option><option value="code">Numéro</option><option value="final">Solde final</option></select></label><button id="sharePrint" class="secondary">Imprimer / PDF</button></div><div id="sharePreviewRows"></div><div class="card" id="sharePreviewTotals"></div><div id="shareMemberDetail"></div></div>`);document.querySelector('#modal .modal').classList.add('wide-detail','partage-modal');
 const render=()=>{let q=$('#shareSearch').value.toLocaleLowerCase('fr').trim(),sort=$('#shareSort').value;let rows=records.filter(x=>(x.name+' '+x.code).toLocaleLowerCase('fr').includes(q)).sort((a,b)=>sort==='final'?b.final-a.final:String(a[sort]).localeCompare(String(b[sort]),'fr'));$('#sharePreviewRows').innerHTML=`<div class="table-wrap partage-wide"><table><thead><tr><th>N°</th>${cols.map(x=>`<th>${x[1]}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="share-member-row" data-member="${escape(r.id)}"><td>${i+1}</td>${cols.map(([k])=>`<td class="${k==='final'&&r.final<0?'debt-due':''}">${['name','code'].includes(k)?escape(r[k]):['shares','meetings','present','absent','loanCount'].includes(k)?r[k]:money(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>{const m=records.find(x=>x.id===b.dataset.member);$('#shareMemberDetail').innerHTML=`<div class="card"><h3>${escape(m.name)} · ${escape(m.code)}</h3><p>Part estimée : <strong>${money(m.share)}</strong></p><p>Total des retenues : ${money(m.fineUnpaid+m.loanRemaining+m.penaltyUnpaid+m.solidUnpaid)}</p><p class="${m.final<0?'debt-due':''}">${m.final<0?'Reste dû par le membre':m.final===0?'Solde nul':'Montant estimé à recevoir'} : <strong>${money(Math.abs(m.final))}</strong></p></div>`})};
 $('#shareSearch').oninput=render;$('#shareSort').onchange=render;$('#sharePrint').onclick=()=>window.print();render();const t=d.summary;$('#sharePreviewTotals').innerHTML=`<h3>Synthèse du cycle</h3><div class="partage-totals">${[['Membres',t.members],['Parts',t.shares],['Épargne',t.savings],['Bénéfice théorique brut',t.theoretical],['Parts estimées',t.allShares],['Amendes impayées',t.fineUnpaid],['Crédits restants',t.loanRemaining],['Pénalités impayées',t.penaltyUnpaid],['Solidarités impayées',t.solidUnpaid],['Retenues',t.totalRetained],['Soldes positifs',t.positive],['Soldes négatifs',t.negative],['Écart de contrôle',t.control]].map(([k,v],i)=>`<div><span>${k}</span><strong class="${k==='Écart de contrôle'&&v!==0?'debt-due':''}">${['Membres','Parts'].includes(k)?v:money(v)}</strong></div>`).join('')}</div><p class="muted">Contrôle : somme algébrique des soldes = parts estimées − retenues. Les sommes sont estimatives et les éventuelles compensations doivent être validées séparément.</p>`;
}
async function preview(){let cycles=cache.cycles||(await req('/api/load?section=cycles')).data;let cy=cycles.find(x=>x.status==='active');if(!cy)return toast('Aucun cycle actif');let d=(await req('/api/save',{section:'distribution_preview',data:{cycle_id:cy.id}})).data;openModal('Simulation de partage',`<p>Épargne : <strong>${money(d.total)}</strong></p><p>Bénéfice net encaissé moins dépenses : <strong>${money(d.profit)}</strong></p><div class="hint">${escape(d.eligible?'Préconditions simplifiées remplies ; distribution définitive non activée.':'Distribution bloquée : '+d.reason)}</div><div class="table-wrap"><table><tr><th>Membre (ID)</th><th>Épargne</th><th>Part de bénéfice</th></tr>${d.rows.map(x=>`<tr><td>${escape(x.member_id.slice(0,8))}</td><td>${money(x.amount)}</td><td>${money(x.share)}</td></tr>`).join('')}</table></div><p class="muted">Simulation informative : aucun versement ni clôture automatique.</p>`)}
async function superadmin(){let [orgs,users,resets]=await Promise.all(['organizations','users','reset_requests'].map(s=>req('/api/load?section='+s).then(r=>r.data)));$('#view').innerHTML=`<div class="card"><div class="toolbar"><h3>Associations (${orgs.length})</h3><button class="primary" id="createOrg">+ Nouvelle association</button></div><div class="table-wrap"><table><tr><th>Nom</th><th>Identifiant</th><th>Statut</th><th>Formule</th><th>Expiration</th><th>Actions</th></tr>${orgs.map(o=>`<tr><td>${escape(o.name)}</td><td><small>${escape(o.id)}</small></td><td>${escape(labelValue(o.status))}</td><td>${escape(labelValue(o.plan))}</td><td>${new Date(o.plan_expires_at).toLocaleDateString('fr-FR')}</td><td><button class="secondary" data-status="${o.id}" data-current="${o.status}">Activer / Suspendre</button> <button class="secondary" data-plan="${o.id}">Formule</button> <button class="secondary danger" data-archive="${o.id}">Archiver</button></td></tr>`).join('')}</table></div></div><div class="card"><div class="toolbar"><h3>Comptes utilisateurs</h3><button class="primary" id="createAdmin">+ Créer administrateur</button></div><div class="table-wrap"><table><tr><th>Utilisateur</th><th>E-mail</th><th>Rôle</th><th>Actions</th></tr>${users.filter(x=>x.role!=='superadmin').map(x=>`<tr><td>${escape(x.name)}</td><td>${escape(x.email)}</td><td>${escape(labelValue(x.role))}</td><td><button class="secondary" data-reset="${x.id}">Réinitialiser</button> <button class="secondary" data-user-status="${x.id}" data-active="${x.active}">${x.active?'Désactiver':'Activer'}</button></td></tr>`).join('')}</table></div></div><div class="card"><h3>Demandes de mot de passe (${resets.length})</h3>${resets.map(r=>`<p>${escape(r.name)} (${escape(r.email)}) <button class="secondary" data-reset="${r.user_id}" data-request="${r.id}">Assister</button></p>`).join('')||'<p>Aucune demande</p>'}</div>`;
$('#createOrg').onclick=()=>{openModal('Créer une association',`<form id="orgForm"><label>Nom<input name="name" required></label><label>Localité<input name="locality"></label><button class="primary full">Créer</button></form>`);$('#orgForm').onsubmit=async e=>{e.preventDefault();try{await req('/api/save',{section:'organization',data:Object.fromEntries(new FormData(e.target))});closeModal();show('superadmin')}catch(er){toast(er.message)}}};$('#createAdmin').onclick=()=>userForm(true);
document.querySelectorAll('[data-status]').forEach(x=>x.onclick=async()=>{try{await req('/api/save',{section:'organization_status',data:{id:x.dataset.status,status:x.dataset.current==='active'?'inactive':'active'}});show('superadmin')}catch(e){toast(e.message)}});
document.querySelectorAll('[data-archive]').forEach(x=>x.onclick=async()=>{if(!confirm('Archiver cette association ? Tous ses comptes perdront accès. Les données financières resteront conservées.'))return;try{await req('/api/save',{section:'organization_status',data:{id:x.dataset.archive,status:'archived'}});show('superadmin')}catch(e){toast(e.message)}});document.querySelectorAll('[data-plan]').forEach(x=>x.onclick=()=>{openModal('Modifier la formule',`<select id="newPlan"><option value="free">Gratuit · 10 jours</option><option value="standard">Standard · 30 jours</option><option value="business">Professionnel · 365 jours</option></select><button class="primary full" id="savePlan">Enregistrer</button>`);$('#savePlan').onclick=async()=>{try{await req('/api/save',{section:'organization_plan',data:{id:x.dataset.plan,plan:$('#newPlan').value}});closeModal();show('superadmin')}catch(e){toast(e.message)}}});
document.querySelectorAll('[data-reset]').forEach(x=>x.onclick=()=>resetUser(x.dataset.reset,x.dataset.request));document.querySelectorAll('[data-user-status]').forEach(x=>x.onclick=async()=>{try{await req('/api/save',{section:'user_status',data:{id:x.dataset.userStatus,active:Number(x.dataset.active)?0:1}});show('superadmin')}catch(e){toast(e.message)}})}
function resetUser(uid,request_id){openModal('Réinitialisation du mot de passe',`<form id="resetUserForm"><label>Nouveau mot de passe (12 caractères minimum)<div class="password-wrap"><input id="resetPassword" type="password" minlength="12" required><button type="button" class="eye" data-eye="resetPassword">◉</button></div></label><button class="primary full">Réinitialiser et révoquer les sessions</button></form>`);wireEyes();$('#resetUserForm').onsubmit=async e=>{e.preventDefault();try{await req('/api/save',{section:'user_reset',data:{id:uid,password:$('#resetPassword').value,request_id}});closeModal();show('superadmin')}catch(er){toast(er.message)}}}
(async()=>{try{let r=await req('/api/session');if(r&&r.user){csrf=r.csrf||csrf;await enter()}}catch{$('#login').hidden=false;$('#app').hidden=true}})();

